head.script:
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일(wframe_SKT-317_(WSQ-952)_main.xml)을 실행 후 XML데이터를 이용한 첫번째 캘린더 이미지를 클릭하고 날짜를 2016.08월로 선택한다.
    //1. Execute the sample file (wframe_SKT-317_ (WSQ-952) _main.xml), click the first calendar image using XML data, and select the date as 2016.08 month.
    //Verify step 1. August 1, 3, 5, and 8 are shown in red.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar1_calendar_selectbox_year_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar1_calendar_selectbox_year_itemTable_38').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar1_calendar_selectbox_month_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar1_calendar_selectbox_month_itemTable_7').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //mobile
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar1_calendar').gotoYear(2016)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar1_calendar').gotoMonth(8)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar1_calendar_cell_0_2').click()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wfm_main_inputCalendar1_calendar_cell_0_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wfm_main_inputCalendar1_calendar_cell_0_3').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wfm_main_inputCalendar1_calendar_cell_0_5').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wfm_main_inputCalendar1_calendar_cell_1_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. DataList 데이터를 이용한 두번째 캘린더 이미지를 클릭하여 날짜를 2016.08월로 선택한다.
    //2. Click on the second calendar image using DataList data and select the date as 2016.08 month.
    //Verify step 2. As in No. 1, August 1, 3, 5, and 8 are shown in red.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar2_calendar_selectbox_year_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar2_calendar_selectbox_year_itemTable_38').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar2_calendar_selectbox_month_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar2_calendar_selectbox_month_itemTable_7').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //mobile
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar2_calendar').gotoYear(2016)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar2_calendar').gotoMonth(8)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wfm_main_inputCalendar2_calendar_cell_0_2').click()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wfm_main_inputCalendar2_calendar_cell_0_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wfm_main_inputCalendar2_calendar_cell_0_3').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wfm_main_inputCalendar2_calendar_cell_0_5').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wfm_main_inputCalendar2_calendar_cell_1_1').css('color') == 'rgb(255, 0, 0)'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 01-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
